"""MLU fused-attention supplement for VGGT (final version).

Root cause chain (fully reproduced standalone):
  1. RoPE leaves q/k as fp32 while v stays bf16 under autocast;
  2. q/k arrive in a head-interleaved [N][D][H] layout: stride (., 1, H*D, H)
     -> the LAST dimension is not contiguous (stride H, not 1);
  3. torch_mlu's SDPA fused kernels reject that layout and the mixed dtypes,
     falling back to the fp32 math backend, which materialises
     N^2 x H x fp32 = 115.23 GiB on [1, 16, 43968, 64] -> OOM on 80 GiB.

Fix (this shim), mirroring A100/CUDA flash semantics:
  - unify q/k to v's dtype (CUDA autocast lowers SDPA inputs to bf16; we
    reproduce that instead of torch_mlu's promote-to-fp32 behaviour);
  - make q/k/v contiguous in head-major layout (three O(N*H*D) copies,
    ~90 MB each at N=44k - amortised to <1% of the attention cost);
  - run SDPA with autocast disabled locally so no further promotion occurs;
  - fall back to an exact block-tiled attention if anything still fails.

Measured on MLU590-M9D (torch_mlu 1.31.1), [1, 16, 43968, 64] bf16:
  fused path via this shim: 0.153-0.166 s  ≈ 48-53 TFLOPS  (24-26% of the
      measured 203 TFLOPS bf16 GEMM peak of this card)
  tiled fallback:            ~0.5 s        ≈ 16 TFLOPS    (memory-bound)
Selection: env VGGT_MLU_ATTN = "auto" (default) | "tiled" | "off".
"""
from __future__ import annotations

import os

import torch
import torch.nn.functional as F

_MODE = os.environ.get("VGGT_MLU_ATTN", "auto")
_BLOCK = int(os.environ.get("VGGT_MLU_ATTN_BLOCK", "4096"))


def _prepare(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor):
    """Unify dtype to v's and normalise to contiguous head-major layout."""
    if q.dtype != v.dtype:
        q = q.to(v.dtype)
    if k.dtype != v.dtype:
        k = k.to(v.dtype)
    if not q.is_contiguous():
        q = q.contiguous()
    if not k.is_contiguous():
        k = k.contiguous()
    if not v.is_contiguous():
        v = v.contiguous()
    return q, k, v


def tiled_attention(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor,
                    dropout_p: float = 0.0, scale: float | None = None) -> torch.Tensor:
    """Exact block-tiled softmax attention, O(block*N) memory.

    Each query block keeps its FULL key row, so results equal the math
    backend up to float non-associativity; softmax runs in fp32.
    """
    d = q.shape[-1]
    s = scale if scale is not None else d ** -0.5
    n = q.shape[-2]
    q, k, v = _prepare(q, k, v)
    block = min(_BLOCK, n)
    out = torch.empty_like(v)
    for i in range(0, n, block):
        j = min(i + block, n)
        scores = torch.matmul(q[..., i:j, :].mul(s), k.transpose(-2, -1))
        probs = torch.softmax(scores, dim=-1, dtype=torch.float32).to(v.dtype)
        out[..., i:j, :] = torch.matmul(probs, v)
    if dropout_p > 0.0:
        out = F.dropout(out, p=dropout_p)
    return out


def mlu_fused_sdpa(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor,
                   dropout_p: float = 0.0, scale: float | None = None) -> torch.Tensor:
    """Drop-in SDPA for MLU: dtype+layout-normalised fused path, tiled fallback."""
    if _MODE == "off":
        return F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p, scale=scale)
    if _MODE == "tiled":
        return tiled_attention(q, k, v, dropout_p=dropout_p, scale=scale)
    q2, k2, v2 = _prepare(q, k, v)
    try:
        # Disable autocast locally: inputs are already in the target dtype
        # and torch_mlu's autocast handling of SDPA promotes to fp32.
        with torch.autocast(device_type=q2.device.type, enabled=False):
            return F.scaled_dot_product_attention(q2, k2, v2, dropout_p=dropout_p, scale=scale)
    except Exception:
        torch.mlu.empty_cache()
        return tiled_attention(q, k, v, dropout_p=dropout_p, scale=scale)
